command:
$ErrorActionPreference = 'Stop'
$start = [datetime]'2026-09-24T12:11:43Z'
$end = [datetime]'2026-09-27T12:11:43Z'
function Read-Events($filter) {
    try { @(Get-WinEvent -FilterHashtable $filter -ErrorAction Stop) }
    catch { if ($_.FullyQualifiedErrorId -like 'NoMatchingEventsFound*') { @() } else { throw } }
}
$events = @(Read-Events @{LogName='Security';Id=4624,4625,4778,4801,1102,4719;StartTime=$start;EndTime=$end})
$rows = @(foreach ($e in $events) {
    $xml = [xml]$e.ToXml()
    $d = @{}
    foreach ($n in $xml.Event.EventData.Data) { $d[$n.Name] = [string]$n.'#text' }
    [pscustomobject]@{
        TimeUtc=$e.TimeCreated.ToUniversalTime().ToString('o');RecordId=$e.RecordId;EventId=$e.Id
        Account=$(if ($d.TargetUserName) {$d.TargetUserName} else {$d.AccountName})
        Domain=$d.TargetDomainName;LogonType=$d.LogonType;Status=$d.Status;SubStatus=$d.SubStatus
        Auth=$d.AuthenticationPackageName;LogonProcess=$d.LogonProcessName;Process=$d.ProcessName
        SourceAddress=$d.IpAddress
    }
})
$success = @($rows | Where-Object EventId -eq 4624)
$summary = @($success | Group-Object Account,LogonType | ForEach-Object {
    $g = @($_.Group | Sort-Object TimeUtc)
    [pscustomobject]@{Account=$g[0].Account;LogonType=$g[0].LogonType;Count=$g.Count;FirstUtc=$g[0].TimeUtc;LastUtc=$g[-1].TimeUtc}
})
$interactive = @($success | Where-Object {$_.LogonType -in @('2','7','10','11','12','13') -and $_.Account -notmatch '^(DWM-|UMFD-|SYSTEM$|LOCAL SERVICE$|NETWORK SERVICE$)'})
$session = @(Read-Events @{LogName='Microsoft-Windows-TerminalServices-LocalSessionManager/Operational';Id=21,25;StartTime=$start;EndTime=$end} | ForEach-Object {
    $x=[xml]$_.ToXml()
    [pscustomobject]@{TimeUtc=$_.TimeCreated.ToUniversalTime().ToString('o');EventId=$_.Id;RecordId=$_.RecordId;Account=[string]$x.Event.UserData.EventXML.User}
})
$oldest = Get-WinEvent -LogName Security -Oldest -MaxEvents 1
$newest = Get-WinEvent -LogName Security -MaxEvents 1
$auditLogon = auditpol /get /subcategory:'Logon' | Out-String
if ($LASTEXITCODE -ne 0) { throw 'Logon audit query failed' }
$auditOther = auditpol /get /subcategory:'Other Logon/Logoff Events' | Out-String
if ($LASTEXITCODE -ne 0) { throw 'Other logon audit query failed' }
[pscustomobject]@{
    HostName=$env:COMPUTERNAME;CollectedUtc=[datetime]::UtcNow.ToString('o')
    StartUtc=$start.ToUniversalTime().ToString('o');EndUtc=$end.ToUniversalTime().ToString('o')
    OldestSecurityEventUtc=$oldest.TimeCreated.ToUniversalTime().ToString('o')
    NewestSecurityEventUtc=$newest.TimeCreated.ToUniversalTime().ToString('o')
    Total4624=$success.Count;SuccessSummary=$summary
    HumanInteractiveSuccesses=$interactive
    Failures=@($rows | Where-Object EventId -eq 4625 | Sort-Object TimeUtc)
    OtherSecurityEvents=@($rows | Where-Object {$_.EventId -notin @(4624,4625)})
    TerminalSessionEvents=$session
    ConsoleUser=(Get-CimInstance Win32_ComputerSystem).UserName
    LastBootUtc=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o')
    AuditLogon=$auditLogon;AuditOtherLogon=$auditOther
} | ConvertTo-Json -Depth 7 -Compress
